  7: {'bbox':(1,6,11,8),'pts':[(1,6),(1,7),(2,6),(10,8),(11,7),(11,8)],'target':1},
  6: {'bbox':(4,6,7,13),'pts':[(4,6),(4,7),(5,6),(6,13),(7,12),(7,13)],'target':8},
  3: {'bbox':(5,8,8,10),'pts':[(5,8),(5,9),(6,8),(7,10),(8,9),(8,10)],'target':4},
  2: {'bbox':(6,13,10,16),'pts':[(6,15),(6,16),(7,16),(9,13),(10,13),(10,14)],'target':4},
}
protected={pt for p in pairs.values() for pt in p['pts']}
# handle mapped square color 8 (non-table components not in legend); recolor the 2x2 component only
for r in (1,2):
 for c in (1,2): H[r,c]=2
# fill mapped boxes in descending area; skip protected L endpoints
for color,p in sorted(pairs.items(),key=lambda kv:(kv[1]['bbox'][2]-kv[1]['bbox'][0]+1)*(kv[1]['bbox'][3]-kv[1]['bbox'][1]+1),reverse=True):
 r1,c1,r2,c2=p['bbox']; target=p['target']
 for r in range(r1,r2+1):
  for c in range(c1,c2+1):
   if (r,c) not in protected: H[r,c]=target
print('\n'.join(' '.join(map(str,row)) for row in H))
